#include <stdio.h>
#include <stdlib.h>

#define MAX_NODES 64
static long value[MAX_NODES];
static int next[MAX_NODES];
static int head = -1;
static int used = 0;

static void insert_sorted(long v) {
    int idx = used++;
    value[idx] = v;
    next[idx] = -1;
    if (head == -1 || value[head] > v) {
        next[idx] = head;
        head = idx;
        return;
    }
    int cur = head;
    while (next[cur] != -1 && value[next[cur]] <= v) {
        cur = next[cur];
    }
    next[idx] = next[cur];
    next[cur] = idx;
}

static void print_list(void) {
    int cur = head;
    while (cur != -1) {
        printf("%ld", value[cur]);
        cur = next[cur];
        if (cur != -1) putchar(' ');
    }
    putchar('\n');
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    int limit = argc - 1;
    if (limit > MAX_NODES) limit = MAX_NODES;
    for (int i = 0; i < limit; ++i) {
        long v = strtol(argv[i+1], NULL, 10);
        insert_sorted(v);
    }
    print_list();
    return 0;
}
